<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">birc</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> create</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> bookstore</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> --yes</span></span>
